// TramDot: the 7-row dot-matrix font (2-dot strokes, 1-dot letter gap) of the sports faces. Generated by
// tools/gen_tramdot.py from the TramDot glyph table; do not edit. Header only.
#pragma once

#include "FaceKit.h"

namespace facekit {

struct TramGlyph { uint8_t w; uint8_t rows[7]; uint8_t tail; };  // row 0 = top; left dot = bit (w-1); tail = the row below the baseline (only the Q has one)

inline const TramGlyph &tramGlyph(char c) {
  static const TramGlyph G[] = {
    {6, {0x1E, 0x33, 0x33, 0x3F, 0x33, 0x33, 0x33}, 0x00},  // A
    {6, {0x3E, 0x33, 0x33, 0x3E, 0x33, 0x33, 0x3E}, 0x00},  // B
    {6, {0x1E, 0x33, 0x30, 0x30, 0x30, 0x33, 0x1E}, 0x00},  // C
    {6, {0x3E, 0x33, 0x33, 0x33, 0x33, 0x33, 0x3E}, 0x00},  // D
    {6, {0x3F, 0x30, 0x30, 0x3E, 0x30, 0x30, 0x3F}, 0x00},  // E
    {6, {0x3F, 0x30, 0x30, 0x3E, 0x30, 0x30, 0x30}, 0x00},  // F
    {6, {0x1E, 0x33, 0x30, 0x37, 0x33, 0x33, 0x1E}, 0x00},  // G
    {6, {0x33, 0x33, 0x33, 0x3F, 0x33, 0x33, 0x33}, 0x00},  // H
    {4, {0x0F, 0x06, 0x06, 0x06, 0x06, 0x06, 0x0F}, 0x00},  // I
    {6, {0x0F, 0x06, 0x06, 0x06, 0x06, 0x36, 0x1C}, 0x00},  // J
    {7, {0x63, 0x66, 0x6C, 0x78, 0x6C, 0x66, 0x63}, 0x00},  // K
    {6, {0x30, 0x30, 0x30, 0x30, 0x30, 0x30, 0x3F}, 0x00},  // L
    {7, {0x63, 0x77, 0x7F, 0x6B, 0x63, 0x63, 0x63}, 0x00},  // M
    {7, {0x63, 0x73, 0x7B, 0x6F, 0x67, 0x63, 0x63}, 0x00},  // N
    {6, {0x1E, 0x33, 0x33, 0x33, 0x33, 0x33, 0x1E}, 0x00},  // O
    {6, {0x3E, 0x33, 0x33, 0x3E, 0x30, 0x30, 0x30}, 0x00},  // P
    {6, {0x1E, 0x33, 0x33, 0x33, 0x33, 0x33, 0x1E}, 0x03},  // Q
    {6, {0x3E, 0x33, 0x33, 0x3E, 0x3C, 0x36, 0x33}, 0x00},  // R
    {6, {0x1F, 0x30, 0x30, 0x1E, 0x03, 0x03, 0x3E}, 0x00},  // S
    {6, {0x3F, 0x0C, 0x0C, 0x0C, 0x0C, 0x0C, 0x0C}, 0x00},  // T
    {6, {0x33, 0x33, 0x33, 0x33, 0x33, 0x33, 0x1E}, 0x00},  // U
    {7, {0x63, 0x63, 0x63, 0x63, 0x36, 0x1C, 0x08}, 0x00},  // V
    {7, {0x63, 0x63, 0x63, 0x6B, 0x7F, 0x77, 0x63}, 0x00},  // W
    {7, {0x63, 0x77, 0x3E, 0x1C, 0x3E, 0x77, 0x63}, 0x00},  // X
    {6, {0x33, 0x33, 0x1E, 0x0C, 0x0C, 0x0C, 0x0C}, 0x00},  // Y
    {6, {0x3F, 0x03, 0x06, 0x0C, 0x18, 0x30, 0x3F}, 0x00},  // Z
    {5, {0x0E, 0x1B, 0x1B, 0x1B, 0x1B, 0x1B, 0x0E}, 0x00},  // 0
    {4, {0x06, 0x0E, 0x06, 0x06, 0x06, 0x06, 0x0F}, 0x00},  // 1
    {6, {0x1E, 0x33, 0x03, 0x06, 0x0C, 0x18, 0x3F}, 0x00},  // 2
    {6, {0x3E, 0x03, 0x03, 0x1E, 0x03, 0x03, 0x3E}, 0x00},  // 3
    {6, {0x06, 0x0E, 0x1E, 0x36, 0x3F, 0x06, 0x06}, 0x00},  // 4
    {6, {0x3F, 0x30, 0x3E, 0x03, 0x03, 0x33, 0x1E}, 0x00},  // 5
    {6, {0x1E, 0x30, 0x30, 0x3E, 0x33, 0x33, 0x1E}, 0x00},  // 6
    {6, {0x3F, 0x03, 0x06, 0x0C, 0x18, 0x18, 0x18}, 0x00},  // 7
    {6, {0x1E, 0x33, 0x33, 0x1E, 0x33, 0x33, 0x1E}, 0x00},  // 8
    {6, {0x1E, 0x33, 0x33, 0x1F, 0x03, 0x03, 0x1E}, 0x00},  // 9
    {2, {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, 0x00},  //  
    {1, {0x00, 0x00, 0x01, 0x00, 0x00, 0x01, 0x00}, 0x00},  // :
    {6, {0x00, 0x00, 0x00, 0x3F, 0x00, 0x00, 0x00}, 0x00},  // -
    {1, {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01}, 0x00},  // .
    {6, {0x03, 0x03, 0x06, 0x0C, 0x18, 0x30, 0x30}, 0x00},  // /
    {6, {0x1C, 0x36, 0x3C, 0x18, 0x3F, 0x36, 0x1F}, 0x00},  // &
    {2, {0x01, 0x01, 0x02, 0x00, 0x00, 0x00, 0x00}, 0x00},  // '
    {2, {0x03, 0x03, 0x03, 0x03, 0x03, 0x00, 0x03}, 0x00},  // !
  };
  static const char K[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 :-./&'!";
  for (int i = 0; K[i]; i++) if (K[i] == c) return G[i];
  if (c >= 'a' && c <= 'z') return tramGlyph(c - 32);
  return G[36];  // unknown: a space
}

inline int tramWidth(const char *s) {
  int n = 0;
  for (; *s; s++) n += tramGlyph(*s).w + 1;
  return n ? n - 1 : 0;
}

// y = top row of the 7-row glyphs (the Q's tail is the row under them); dots beyond [minX, maxX) are not drawn
inline void tramText(MatrixPanel_I2S_DMA &d, const char *s, int x, int y, uint16_t color, int minX = 0, int maxX = W) {
  for (; *s; s++) {
    const TramGlyph &g = tramGlyph(*s);
    for (int row = 0; row < 7; row++)
      for (int col = 0; col < g.w; col++)
        if ((g.rows[row] >> (g.w - 1 - col) & 1) && x + col >= minX && x + col < maxX && y + row >= 0 && y + row < H) put(d, x + col, y + row, color);
    for (int col = 0; col < g.w; col++)
      if ((g.tail >> (g.w - 1 - col) & 1) && x + col >= minX && x + col < maxX && y + 7 >= 0 && y + 7 < H) put(d, x + col, y + 7, color);
    x += g.w + 1;
  }
}

}  // namespace facekit
